import {LEVELS,getLevel} from './levels.js';
import {LANGUAGES,getLanguage} from './languages.js';
import {makeQuestion,grade,winners} from './engine.js';
const $=id=>document.getElementById(id);
let key='',question=null,answered=0,points=0,streak=0,busy=false,controller,recent={},startAfterConnect=false;
function scoreboard(){$('answered').textContent=answered;$('points').textContent=points;$('streak').textContent=streak;}
function render(){if(!question)return;$('welcome').hidden=true;$('round').hidden=false;const spec=getLanguage(question.language);$('sourceText').textContent=question.source;$('sourceText').lang=spec.code;$('sourceText').dir=spec.direction;$('roundNumber').textContent=`ROUND ${question.selected===null?answered+1:answered} · ${question.level}`;$('roundTopic').textContent=question.topic;const revealed=question.selected!==null;const best=revealed?winners(question.scores):[];$('options').replaceChildren(...question.options.map((text,i)=>{const b=document.createElement('button');b.className='option';b.disabled=busy||revealed;const letter=document.createElement('span');letter.className='letter';letter.textContent='ABCD'[i];const answer=document.createElement('span');answer.className='answer';answer.textContent=text;b.append(letter,answer);if(revealed){if(best.includes(i))b.classList.add('best');if(i===question.selected)b.classList.add('chosen');const score=document.createElement('span');score.className='score';const number=document.createElement('strong');number.textContent=question.scores[i].toFixed(6);const label=document.createElement('small');label.textContent=[best.includes(i)?'Highest similarity':'Cosine similarity',i===question.selected?'Your choice':''].filter(Boolean).join(' · ');score.append(number,label);b.append(score);}b.onclick=()=>choose(i);return b;}));$('reveal').hidden=!revealed;if(revealed){$('resultLabel').textContent=question.correct?'A MATCH · +1 POINT':'ANOTHER LOOK';$('resultTitle').textContent=question.correct?'You found the closest match.':'The embeddings chose differently.';$('resultDescription').textContent=`${best.length>1?'Options':'Option'} ${best.map(i=>'ABCD'[i]).join(' and ')} ${best.length>1?'share':'has'} the highest similarity to the ${question.language} sentence.${question.correct?'':' Compare the choices: a high score can still overlook a meaningful difference.'}`;}scoreboard();}
function choose(i){if(busy||!question||question.selected!==null)return;question=grade(question,i);answered++;if(question.correct){points++;streak++;}else streak=0;render();$('resultTitle').focus();}
function setBusy(value){busy=value;$('start').disabled=$('next').disabled=$('connectionButton').disabled=$('language').disabled=$('level').disabled=value;$('cancel').hidden=!value;$('retry').hidden=true;if(question)render();}
async function nextQuestion(){if(busy)return;if(!key){startAfterConnect=true;$('connection').showModal();return;}controller=new AbortController();$('error').hidden=true;setBusy(true);try{const next=await makeQuestion(key,recent[$('language').value]||[],{language:$('language').value,level:$('level').value,signal:controller.signal,onStatus:text=>{$('status').textContent=text;}});question=next;recent[next.language]=[...(recent[next.language]||[]).slice(-11),next.source];$('status').textContent='Choose one answer to reveal all four scores.';render();$('chooseHeading').setAttribute('tabindex','-1');$('chooseHeading').focus();}catch(e){$('error').textContent=e.message;$('error').hidden=false;$('status').textContent='No new question was added.';}finally{setBusy(false);$('retry').hidden=$('error').hidden;}}
$('start').onclick=$('next').onclick=$('retry').onclick=nextQuestion;$('cancel').onclick=()=>controller?.abort();
$('connectionButton').onclick=()=>{startAfterConnect=false;$('connection').showModal();};$('close').onclick=()=>{startAfterConnect=false;$('connection').close();};$('connection').addEventListener('cancel',()=>{startAfterConnect=false;});
$('keyForm').onsubmit=e=>{e.preventDefault();key=$('key').value.trim();if(!key)return;$('key').value='';$('connection').close();$('connectionButton').textContent='ARC key ready';const start=startAfterConnect;startAfterConnect=false;if(start)nextQuestion();};$('forget').onclick=()=>{key='';$('key').value='';startAfterConnect=false;$('connectionButton').textContent='ARC connection';$('connection').close();};

for(const language of LANGUAGES){const option=document.createElement('option');option.value=language.name;option.textContent=language.name;$('language').append(option);}
$('language').value='French';
function updateLanguage(){const spec=getLanguage($('language').value);$('languagePair').textContent=`${spec.name.toUpperCase()} → ENGLISH`;$('greeting').textContent=spec.greeting;$('greeting').lang=spec.code;$('greeting').dir=spec.direction;$('classicalNote').hidden=!['grc','la'].includes(spec.code);}
$('language').onchange=()=>{if(busy)return;question=null;startAfterConnect=false;$('round').hidden=true;$('welcome').hidden=false;$('reveal').hidden=true;$('options').replaceChildren();$('sourceText').textContent='';$('error').hidden=true;$('retry').hidden=true;updateLanguage();$('status').textContent=`Ready for ${$('language').value}. Your session score is kept. Select Let’s play for a new round.`;};
updateLanguage();

for(const [code,spec] of Object.entries(LEVELS)){const option=document.createElement('option');option.value=code;option.textContent=`${code} · ${spec.label}`;$('level').append(option);}
$('level').value='B1';
function updateLevel(){const spec=getLevel($('level').value);$('levelTheme').textContent=spec.theme;$('levelTopics').replaceChildren(...spec.topics.map(topic=>{const li=document.createElement('li');const name=document.createElement('strong');name.textContent=topic.name;li.append(name,document.createTextNode(' — '+topic.details));return li;}));}
$('level').onchange=()=>{updateLevel();$('status').textContent=`${$('level').value} selected for your next round. The current round and session score are unchanged.`;};
updateLevel();
